/**
 * carousel — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/carousel.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
import * as React from "react"
import { ArrowLeft, ArrowRight } from "lucide-react"
import useEmblaCarousel from "embla-carousel-react"
import Autoplay from "embla-carousel-autoplay"
import { Button } from "@/components/ui/button"
import { InView } from "@/components/primitives/in-view"
import { cn } from "@/lib/utils"

// ── Types ────────────────────────────────────────────────────────────────────
export type Slide = {
  id?: string | number
  image?: string
  imageAlt?: string
  eyebrow?: string
  title?: string
  body?: string
  action?: { label: string; href: string }
  /** Provide fully custom card content instead of the image+copy layout. */
  content?: React.ReactNode
}

export type ContentCarouselProps = {
  eyebrow?: string
  title?: string
  slides: Slide[]
  /** Drag + arrows are on by default (set false to disable drag, arrows toggle). */
  showArrows?: boolean
  showIndicator?: boolean
  /** Show N slides side-by-side from lg up (peek carousel). Default 1. */
  perViewLg?: 1 | 2 | 3
  /** Auto-advance every N seconds. 0 disables. Default 0. Respects reduced motion (stays off). */
  autoplay?: number
  className?: string
}

// ── ContentCarousel ──────────────────────────────────────────────────────────

const DEFAULT_SLIDES: Slide[] = [
  {
    id: "s1",
    image: "/frames/frame_0001.webp",
    imageAlt: "Morning light across the studio floor",
    eyebrow: "The studio",
    title: "A calm floor in Jönköping",
    body: "Six chairs, one board and a kettle that never rests. Östergatan 12, Tuesday to Saturday.",
    action: { label: "Book a chair", href: "#book" },
  },
  {
    id: "s2",
    image: "/frames/frame_0003.webp",
    imageAlt: "The colour bar mid-mix",
    eyebrow: "Services",
    title: "Cut & finish — 640 kr",
    body: "One chair, one stylist, all afternoon. The price on the board is the price on the receipt.",
  },
  {
    id: "s3",
    image: "/frames/frame_0005.webp",
    imageAlt: "Prints drying in the back room",
    eyebrow: "The journal",
    title: "Notes from the floor",
    body: "Cuts, care and calm — written between clients, never instead of them.",
    action: { label: "Read the journal", href: "#journal" },
  },
  {
    id: "s4",
    image: "/frames/frame_0007.webp",
    imageAlt: "The front desk and the ledger",
    eyebrow: "Visit us",
    title: "Walk-ins before lunch",
    body: "Two chair hours held back every weekday, 11:30–12:30. First come, first seated.",
    action: { label: "Find us", href: "#visit" },
  },
]

function SlideCard({ slide, perView }: { slide: Slide; perView: number }) {
  if (slide.content) return <>{slide.content}</>
  return (
    <div className="relative flex flex-col overflow-hidden rounded-[24px] border bg-card shadow-sm">
      {slide.image && (
        <div className={cn("relative overflow-hidden", perView > 1 ? "aspect-[4/3]" : "aspect-[16/10] lg:aspect-[21/10]")}>
          <img src={slide.image} alt={slide.imageAlt ?? slide.title ?? ""} loading="lazy" className="absolute inset-0 h-full w-full object-cover" />
        </div>
      )}
      <div className="flex flex-1 flex-col p-6">
        {slide.eyebrow && <p className="font-mono text-[10px] font-bold uppercase tracking-widest text-muted-foreground">{slide.eyebrow}</p>}
        {slide.title && <h3 className={cn("mt-2 font-display font-bold tracking-tight", perView > 1 ? "text-lg" : "text-2xl lg:text-3xl")}>{slide.title}</h3>}
        {slide.body && <p className="mt-2 max-w-prose text-sm font-medium leading-relaxed text-muted-foreground">{slide.body}</p>}
        {slide.action && (
          <a href={slide.action.href} className="mt-4 inline-flex items-center gap-1 text-sm font-bold underline-offset-4 hover:underline" >
            {slide.action.label} <span aria-hidden>→</span>
          </a>
        )}
      </div>
    </div>
  )
}

export function ContentCarousel({
  eyebrow = "Quiet Times Studio",
  title = "Frames from the floor.",
  slides = DEFAULT_SLIDES,
  showArrows = true,
  showIndicator = true,
  perViewLg = 1,
  autoplay = 0,
  className,
}: ContentCarouselProps) {
  const reduce = React.useMemo(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches, [])
  const play = autoplay > 0 && slides.length > 1
  const [emblaRef, emblaApi] = useEmblaCarousel(
    { loop: play, align: "start" },
    play ? [Autoplay({ delay: autoplay * 1000, stopOnInteraction: true, playOnInit: !reduce })] : [],
  )
  const [idx, setIdx] = React.useState(0)
  React.useEffect(() => {
    if (!emblaApi) return
    const onSelect = () => setIdx(emblaApi.selectedScrollSnap())
    onSelect()
    emblaApi.on("select", onSelect)
    return () => { emblaApi.off("select", onSelect) }
  }, [emblaApi])

  if (!slides.length) return null

  return (
    <section className={cn("relative isolate overflow-hidden w-full bg-background text-foreground", className)} aria-roledescription="carousel" aria-label={title ?? "Highlights"}>
        <div className="mx-auto w-full max-w-[1280px] px-5 py-16 sm:px-8 lg:px-8">
          {(eyebrow || title) && (
            <InView variants={{ hidden: { opacity: 0, y: 14 }, visible: { opacity: 1, y: 0 } }} transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }} viewOptions={{ once: true, margin: "-60px" }}>
              <header className="mb-8 flex flex-wrap items-end justify-between gap-4">
                <div className="max-w-2xl">
                  {eyebrow && <p className="font-mono text-[11px] font-bold uppercase tracking-widest text-muted-foreground">{eyebrow}</p>}
                  {title && <h2 className="mt-1 font-display text-3xl font-bold tracking-tight sm:text-4xl">{title}</h2>}
                </div>
                {showArrows && (
                  <div className="flex gap-2">
                    <Button size="icon" variant="outline" onClick={() => emblaApi?.scrollPrev()} aria-label="Previous slide" className="h-11 w-11 rounded-full">
                      <ArrowLeft />
                    </Button>
                    <Button size="icon" variant="outline" onClick={() => emblaApi?.scrollNext()} aria-label="Next slide" className="h-11 w-11 rounded-full">
                      <ArrowRight />
                    </Button>
                  </div>
                )}
              </header>
            </InView>
          )}
          <div className="relative">
            <div className="group/hover relative overflow-hidden">
              <div ref={emblaRef} className="overflow-hidden">
                <div className="flex">
                  {slides.map((s, i) => (
                    <div key={s.id ?? i} className="min-w-0 flex-[0_0_100%] pb-4 pr-4">
                      <SlideCard slide={s} perView={1} />
                    </div>
                  ))}
                </div>
              </div>
              {perViewLg === 1 && showIndicator && (
                <div className="flex justify-center gap-2">
                  {slides.map((s, i) => (
                    <Button
                      key={s.id ?? i}
                      size="icon"
                      variant="ghost"
                      onClick={() => emblaApi?.scrollTo(i)}
                      aria-label={`Go to slide ${i + 1}`}
                      aria-current={i === idx}
                      className={cn("h-2 rounded-full p-0", i === idx ? "w-6 bg-foreground" : "w-2 bg-muted-foreground/40")}
                    />
                  ))}
                </div>
              )}
            </div>

            {perViewLg > 1 && (
              <div className="hidden lg:grid" style={{ gridTemplateColumns: `repeat(${perViewLg}, minmax(0,1fr))`, gap: 16 }}>
                {slides.map((s, i) => (
                  <div key={s.id ?? i}>
                    <SlideCard slide={s} perView={perViewLg} />
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </section>
  )
}

/**
 * carousel — vendored from the UI Engine preset library (axiestudio).
 * Install: npx shadcn@latest add https://ui-engine.pages.dev/r/carousel.json
 * Source of truth: UI/ — do not edit vendored copies blindly.
 */
/**
 * Vendored from motion-primitives (https://motion-primitives.com) by ibelick (MIT).
 * Upstream: https://github.com/ibelick/motion-primitives/blob/main/components/core/carousel.tsx
 *
 * Local craft (HANDCRAFT-CHECKLIST — "never hardcode hex for anything token-able"):
 * the upstream zinc palette classes are replaced with the shadcn token set, so the
 * component themes with the host brandkit and dark mode flips automatically.
 */
'use client';
import type { ReactNode } from 'react';
import { Children, createContext, useContext, useEffect, useRef, useState } from 'react';
import type { Transition } from 'motion/react';
import { motion, useMotionValue } from 'motion/react';
import { cn } from '@/lib/utils';
import { ChevronLeft, ChevronRight } from 'lucide-react';

export type CarouselContextType = {
  index: number;
  setIndex: (newIndex: number) => void;
  itemsCount: number;
  setItemsCount: (newItemsCount: number) => void;
  disableDrag: boolean;
};

const CarouselContext = createContext<CarouselContextType | undefined>(
  undefined
);

function useCarousel() {
  const context = useContext(CarouselContext);
  if (!context) {
    throw new Error('useCarousel must be used within an CarouselProvider');
  }
  return context;
}

export type CarouselProviderProps = {
  children: ReactNode;
  initialIndex?: number;
  onIndexChange?: (newIndex: number) => void;
  disableDrag?: boolean;
};

function CarouselProvider({
  children,
  initialIndex = 0,
  onIndexChange,
  disableDrag = false,
}: CarouselProviderProps) {
  const [index, setIndex] = useState<number>(initialIndex);
  const [itemsCount, setItemsCount] = useState<number>(0);

  const handleSetIndex = (newIndex: number) => {
    setIndex(newIndex);
    onIndexChange?.(newIndex);
  };

  useEffect(() => {
    setIndex(initialIndex);
  }, [initialIndex]);

  return (
    <CarouselContext.Provider
      value={{
        index,
        setIndex: handleSetIndex,
        itemsCount,
        setItemsCount,
        disableDrag,
      }}
    >
      {children}
    </CarouselContext.Provider>
  );
}

export type CarouselProps = {
  children: ReactNode;
  className?: string;
  initialIndex?: number;
  index?: number;
  onIndexChange?: (newIndex: number) => void;
  disableDrag?: boolean;
};

function Carousel({
  children,
  className,
  initialIndex = 0,
  index: externalIndex,
  onIndexChange,
  disableDrag = false,
}: CarouselProps) {
  const [internalIndex, setInternalIndex] = useState<number>(initialIndex);
  const isControlled = externalIndex !== undefined;
  const currentIndex = isControlled ? externalIndex : internalIndex;

  const handleIndexChange = (newIndex: number) => {
    if (!isControlled) {
      setInternalIndex(newIndex);
    }
    onIndexChange?.(newIndex);
  };

  return (
    <CarouselProvider
      initialIndex={currentIndex}
      onIndexChange={handleIndexChange}
      disableDrag={disableDrag}
    >
      <div className={cn('group/hover relative', className)}>
        <div className='overflow-hidden'>{children}</div>
      </div>
    </CarouselProvider>
  );
}

export type CarouselNavigationProps = {
  className?: string;
  classNameButton?: string;
  alwaysShow?: boolean;
};

function CarouselNavigation({
  className,
  classNameButton,
  alwaysShow,
}: CarouselNavigationProps) {
  const { index, setIndex, itemsCount } = useCarousel();

  return (
    <div
      className={cn(
        'pointer-events-none absolute left-[-12.5%] top-1/2 flex w-[125%] -translate-y-1/2 justify-between px-2',
        className
      )}
    >
      <button
        type='button'
        aria-label='Previous slide'
        className={cn(
          'pointer-events-auto h-fit w-fit rounded-full bg-background p-2 transition-opacity duration-300',
          alwaysShow
            ? 'opacity-100'
            : 'opacity-0 group-hover/hover:opacity-100',
          alwaysShow
            ? 'disabled:opacity-40'
            : 'group-hover/hover:disabled:opacity-40',
          classNameButton
        )}
        disabled={index === 0}
        onClick={() => {
          if (index > 0) {
            setIndex(index - 1);
          }
        }}
      >
        <ChevronLeft
          className='stroke-muted-foreground'
          size={16}
        />
      </button>
      <button
        type='button'
        className={cn(
          'pointer-events-auto h-fit w-fit rounded-full bg-background p-2 transition-opacity duration-300',
          alwaysShow
            ? 'opacity-100'
            : 'opacity-0 group-hover/hover:opacity-100',
          alwaysShow
            ? 'disabled:opacity-40'
            : 'group-hover/hover:disabled:opacity-40',
          classNameButton
        )}
        aria-label='Next slide'
        disabled={index + 1 === itemsCount}
        onClick={() => {
          if (index < itemsCount - 1) {
            setIndex(index + 1);
          }
        }}
      >
        <ChevronRight
          className='stroke-muted-foreground'
          size={16}
        />
      </button>
    </div>
  );
}

export type CarouselIndicatorProps = {
  className?: string;
  classNameButton?: string;
};

function CarouselIndicator({
  className,
  classNameButton,
}: CarouselIndicatorProps) {
  const { index, itemsCount, setIndex } = useCarousel();

  return (
    <div
      className={cn(
        'absolute bottom-0 z-10 flex w-full items-center justify-center',
        className
      )}
    >
      <div className='flex space-x-2'>
        {Array.from({ length: itemsCount }, (_, i) => (
          <button
            key={i}
            type='button'
            aria-label={`Go to slide ${i + 1}`}
            onClick={() => setIndex(i)}
            className={cn(
              'h-2 w-2 rounded-full transition-opacity duration-300',
              index === i
                ? 'bg-foreground'
                : 'bg-foreground/50',
              classNameButton
            )}
          />
        ))}
      </div>
    </div>
  );
}

export type CarouselContentProps = {
  children: ReactNode;
  className?: string;
  transition?: Transition;
};

function CarouselContent({
  children,
  className,
  transition,
}: CarouselContentProps) {
  const { index, setIndex, setItemsCount, disableDrag } = useCarousel();
  const [visibleItemsCount, setVisibleItemsCount] = useState(1);
  const dragX = useMotionValue(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const itemsLength = Children.count(children);

  useEffect(() => {
    if (!containerRef.current) {
      return;
    }

    const options = {
      root: containerRef.current,
      threshold: 0.5,
    };

    const observer = new IntersectionObserver((entries) => {
      const visibleCount = entries.filter(
        (entry) => entry.isIntersecting
      ).length;
      setVisibleItemsCount(visibleCount);
    }, options);

    const childNodes = containerRef.current.children;
    Array.from(childNodes).forEach((child) => observer.observe(child));

    return () => observer.disconnect();
  }, [children, setItemsCount]);

  useEffect(() => {
    if (!itemsLength) {
      return;
    }

    setItemsCount(itemsLength);
  }, [itemsLength, setItemsCount]);

  const onDragEnd = () => {
    const x = dragX.get();

    if (x <= -10 && index < itemsLength - 1) {
      setIndex(index + 1);
    } else if (x >= 10 && index > 0) {
      setIndex(index - 1);
    }
  };

  return (
    <motion.div
      drag={disableDrag ? false : 'x'}
      dragConstraints={
        disableDrag
          ? undefined
          : {
              left: 0,
              right: 0,
            }
      }
      dragMomentum={disableDrag ? undefined : false}
      style={{
        x: disableDrag ? undefined : dragX,
      }}
      animate={{
        translateX: `-${index * (100 / visibleItemsCount)}%`,
      }}
      onDragEnd={disableDrag ? undefined : onDragEnd}
      transition={
        transition || {
          damping: 18,
          stiffness: 90,
          type: 'spring',
          duration: 0.2,
        }
      }
      className={cn(
        'flex items-center',
        !disableDrag && 'cursor-grab active:cursor-grabbing',
        className
      )}
      ref={containerRef}
    >
      {children}
    </motion.div>
  );
}

export type CarouselItemProps = {
  children: ReactNode;
  className?: string;
};

function CarouselItem({ children, className }: CarouselItemProps) {
  return (
    <motion.div
      className={cn(
        'w-full min-w-0 shrink-0 grow-0 overflow-hidden',
        className
      )}
    >
      {children}
    </motion.div>
  );
}

export {
  Carousel,
  CarouselProvider,
  CarouselContent,
  CarouselNavigation,
  CarouselIndicator,
  CarouselItem,
  useCarousel,
};

